using System;
using FMODUnity;
using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "Soul Heat", menuName = "Data/Battle/Effects/Sothis/Soul Heat")]
public class SoulHeat : ScriptableObject
{
	private const int maxSoulHeat = 10;

	[Header("On Soul Heat Hit Value Effects")]
	[SerializeField]
	private OnSoulHeatHitValueEffects[] onSoulHitValueEffects;

	[Header("Soul Heat Events")]
	[SerializeField]
	private VoidEvent OnUpdateSoulHeatHUD;

	[Header("Achievement")]
	[SerializeField]
	private AchievementData blazingPrinceAchievementData;

	[Header("SFX")]
	[SerializeField]
	private EventReference soulHeatZeroSFX;

	[SerializeField]
	private EventReference soulHeatTenSFX;

	[NonSerialized]
	[ShowNonSerializedField]
	private int soulHeatCounter;

	[NonSerialized]
	[ShowNonSerializedField]
	public bool innerWarmthEffectActive;

	[NonSerialized]
	public bool CancelNextSoulHeatModification;

	public int MaxSoulHeat => 10;

	public int SoulHeatCounter => soulHeatCounter;

	private bool IsSothisCurrentCharacter()
	{
		return ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName == "Sothis";
	}

	public void ModifySoulHeat(int amount)
	{
		if (!IsSothisCurrentCharacter())
		{
			return;
		}
		if (!CancelNextSoulHeatModification)
		{
			int num = soulHeatCounter;
			soulHeatCounter += amount;
			if (soulHeatCounter > 10)
			{
				if (!ReferenceSingleton<SothisOmensHandler>.Instance.IsFervorousSundialOmenActiveActivateAction())
				{
					soulHeatCounter = Mathf.Clamp(soulHeatCounter, 0, 10);
				}
			}
			else
			{
				soulHeatCounter = Mathf.Clamp(soulHeatCounter, 0, 10);
			}
			if (num != soulHeatCounter)
			{
				ActivateOnSoulHeatHitValueEffects();
				OnUpdateSoulHeatHUD.Raise();
				if (soulHeatCounter == 10)
				{
					ReferenceSingleton<SFXHandler>.Instance.PlaySFX(soulHeatTenSFX);
				}
			}
			if (soulHeatCounter > 10 && soulHeatCounter >= blazingPrinceAchievementData.AchievementVariableAmount)
			{
				blazingPrinceAchievementData.Unlock();
			}
		}
		CancelNextSoulHeatModification = false;
	}

	private void ActivateOnSoulHeatHitValueEffects()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.ActivateBoneKhopeshOmen(soulHeatCounter);
		PlayerEffects component = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();
		for (int i = 0; i < onSoulHitValueEffects.Length; i++)
		{
			if (component.IsEffectActive(onSoulHitValueEffects[i], activateFeedback: false))
			{
				onSoulHitValueEffects[i].OnSoulHeatHitValue(component);
			}
		}
	}

	[Button(null)]
	public void ResetSoulHeat(bool decreaseInnerWarmth = false, bool noSFXResetSoulHeat = false)
	{
		if (!IsSothisCurrentCharacter())
		{
			return;
		}
		PlayerEffects component = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();
		bool num = component.IsInnerWarmthActive();
		if (decreaseInnerWarmth)
		{
			component.IsInnerWarmthActiveDecreaseIt();
		}
		if (!num && soulHeatCounter != 0)
		{
			soulHeatCounter = 0;
			ActivateOnSoulHeatHitValueEffects();
			OnUpdateSoulHeatHUD.Raise();
			if (!noSFXResetSoulHeat)
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(soulHeatZeroSFX);
			}
		}
	}

	[Button(null)]
	private void MoreSoulHeat()
	{
		ModifySoulHeat(1);
	}

	[Button(null)]
	private void LessSoulHeat()
	{
		ModifySoulHeat(-1);
	}
}
